def put(name,data):
    target=OUT/name
    assert target.resolve().is_relative_to(OUT.resolve())
    if isinstance(data,(dict,list)):
        data=json.dumps(data,ensure_ascii=False,indent=2,allow_nan=False)+'\n'
    target.write_text(data,encoding='utf-8')


